import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Position of each candidate relative to the current frontier of S: (cand - max_S) / n, zero if S empty; captures clustering near the leading edge."""
    cand = np.asarray(cand, dtype=float)
    S = np.flatnonzero(chosen)
    if S.size == 0:
        return (cand - 1.0) / float(n)
    frontier = float(S.max() + 1)  # largest chosen number
    return np.clip((cand - frontier) / float(n), -1.0, 1.0)

