def feature(cand, chosen, avail, n, coef):
    """Position of each candidate relative to the current frontier: distance to the largest chosen number, normalised by n, signed (negative = already behind the frontier, positive = ahead)."""
    cand = np.asarray(cand, dtype=np.int64)
