import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Normalised distance from each candidate to the nearest chosen number: D/n, D=n if S empty."""
    S = np.flatnonzero(chosen)
    if S.size == 0:
        return np.ones(cand.shape[0], dtype=float)
    D = np.min(np.abs(cand[:, None] - S[None, :]), axis=1)
    return np.clip(D / n, 0.0, 1.0)

import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Position of each candidate relative to the current frontier of S: signed, saturating (cand - max(S)) / spread, in [-1, 1]."""
    S = np.flatnonzero(chosen) + 1
    c = np.asarray(cand, dtype=float)
    if S.size == 0:
        return np.clip((c - 1.0) / max(n - 1.0, 1.0) * 2.0 - 1.0, -1.0, 1.0)
    hi = float(S.max())
    lo = float(S.min())
    spread = max(hi - lo, 1.0)
    return np.tanh((c - hi) / spread)

import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Normalised position of each candidate, but measured relative to how far the build has progressed: (cand/n - density) where density = |S|/n, i.e. above/below the frontier of chosen numbers."""
    density = chosen.sum() / float(n)
    pos = (np.asarray(cand, dtype=float) - 1.0) / float(n - 1) if n > 1 else np.zeros(len(cand))
    return np.clip(pos - density, -1.0, 1.0)

