import numpy as np

def feature(cand, chosen, avail, n, coef):
    """State-free tent: count of integer offsets t with both partners of v in 1..n, over both coefficient orders, divided by n."""
    a, b, c = int(coef[0]), int(coef[1]), int(coef[2])
    if n <= 0:
        return np.zeros(len(cand), dtype=float)
    v = np.asarray(cand, dtype=np.int64)
    p = v - 1
    q = n - v
    t1 = np.minimum(p // a, q // b)
    t2 = np.minimum(p // b, q // a)
    return (t1 + t2).astype(float) / float(n)

