import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Position of each candidate relative to the largest chosen number: (cand - maxS)/n, clipped to [-1,1]; 0 if S empty."""
    cand = np.asarray(cand, dtype=np.int64)
    if not chosen.any():
        return np.zeros(cand.shape[0], dtype=float)
    top = float(np.flatnonzero(chosen)[-1] + 1)
    return np.clip((cand - top) / float(n), -1.0, 1.0)

import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Inverted-V curvature of normalised position: 1 at pos=0.5, -1 at pos=0 and pos=1."""
    pos = np.clip((cand - 1.0) / max(n - 1, 1), 0.0, 1.0)
    return 1.0 - 2.0 * np.abs(2.0 * pos - 1.0)

import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Quantile of each candidate among still-available numbers minus its quantile in 1..n, clipped to [-1,1]."""
    A = np.flatnonzero(avail) + 1
    nA = A.size
    if nA <= 1:
        return np.zeros(cand.shape[0])
    below = np.searchsorted(A, cand, side='left')
    q = below / (nA - 1)
    p = (cand - 1) / max(n - 1, 1)
    return np.clip(q - p, -1.0, 1.0)

import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Position of candidate relative to the densest part of S: signed normalised distance from the mean of chosen, scaled by S's spread."""
    cand = np.asarray(cand, dtype=float)
    S = np.flatnonzero(chosen) + 1.0
    if S.size == 0:
        # no set yet: fall back to position from the top (mirror of position_frac)
        return np.clip(1.0 - 2.0 * (cand - 1) / float(n - 1), -1.0, 1.0)
    mu = S.mean()
    sd = S.std()
    scale = max(sd, 0.05 * n)
    return np.tanh((cand - mu) / scale)

import numpy as np

def feature(cand, chosen, avail, n, coef):
    """Triangular band on normalised position: clip(1 - |pos - 0.70|/0.30, 0, 1), pos = (cand-1)/(n-1)."""
    cand = np.asarray(cand, dtype=float)
    if n > 1:
        pos = (cand - 1.0) / (n - 1.0)
    else:
        pos = np.zeros_like(cand)
    pos = np.clip(pos, 0.0, 1.0)
    val = 1.0 - np.abs(pos - 0.70) / 0.30
    return np.clip(val, 0.0, 1.0)
